// m20: the Chapel spirits. PUBLIC COPY ONLY: embedded as data URIs so githack does not taint the canvas. ?m20=0 / ?npc=0 -> nothing registered.
(function () {
  if (/[?&]m20=0/.test(location.search) || !window.ASSETS) return;
  if (/[?&]npc=0/.test(location.search)) return;
  const D = {
    s_m20_wick: "data:image/png;base64,",
    s_m20_auberon: "data:image/png;base64,",
    s_m20_brannoch: "data:image/png;base64,",
    s_m20_cecily: "data:image/png;base64,",
    s_m20_isolde: "data:image/png;base64,",
    s_m20_ansel: "data:image/png;base64,",
    s_m20_ozmeth: "data:image/png;base64,",
    s_m20_baron: "data:image/png;base64,"
  };
  for (const k in D) window.ASSETS[k] = D[k];
})();
